  "Scarcity": {"Explanation": "The email creates urgency by implying limited time ('limited time only', 'big savings when you order by June 30, 1999'), quantity ('save $33.95 when you buy two products','save $58.95 when you buy three products') or opportunity."},
  "Authority": {"Explanation": "The email claims credibility through a recognized institution ('Sparks International, an import company based in South Carolina'), a title ('President James Yates'), and a role ('fat-loss specialist')."},
  "Commitment/Consistency": {"Explanation": "The email references prior behavior or choices ('over one million international customers show an average permanent fat loss') to push further action."},
  "Liking": {"Explanation": "The email uses familiarity and flattery by addressing the recipient directly and offering a personalized solution ('now Americans don't have to resort to the pain and expense of liposuction surgery to get immediate results on stubborn fat and cellulite')."},
  "Social proof": {"Explanation": "The email references other people's participation or endorsement ('over one million international customers show an average permanent fat loss')"}
}

